  "answer": "```python\nimport asyncio\nimport time\n\nimport dspy\nfrom dspy.utils.asyncify import get_limiter\n\n\ndef sleeper(delay):\n    time.sleep(delay)\n    return 42\n\n\n# asyncify consults get_limiter() on each call, so context changes retune the shared limiter.\nasync_sleeper = dspy.asyncify(sleeper)\n\n\nasync def timed_run(workers, tasks, delay):\n    with dspy.context(async_max_workers=workers):\n        limiter = get_limiter()\n        print(f\"workers={workers} total_tokens={limiter.total_tokens}\")\n        assert limiter.total_tokens == workers\n        start = time.perf_counter()\n        results = await asyncio.gather(*[async_sleeper(delay) for _ in range(tasks)])\n        elapsed = time.perf_counter() - start\n    return limiter, results, elapsed\n\n\nasync def main():\n    serial_limiter, slow_results, slow_elapsed = await timed_run(1, 8, 0.2)\n    parallel_limiter, fast_results, fast_elapsed = await timed_run(4, 8, 0.2)\n\n    print(\"limiter_is_shared:\", serial_limiter is parallel_limiter)\n    print(\"serialish_elapsed:\", round(slow_elapsed, 2))\n    print(\"parallel_elapsed:\", round(fast_elapsed, 2))\n\n    assert serial_limiter is parallel_limiter\n    assert slow_results == [42] * 8\n    assert fast_results == [42] * 8\n\n    # DSPy reuses one CapacityLimiter and updates its token count from async_max_workers.\n    with dspy.context(async_max_workers=1):\n        assert get_limiter() is serial_limiter\n        assert get_limiter().total_tokens == 1\n    with dspy.context(async_max_workers=4):\n        assert get_limiter() is serial_limiter\n        assert get_limiter().total_tokens == 4\n\n    assert slow_elapsed > 1.4\n    assert fast_elapsed < 0.8\n    assert fast_elapsed < slow_elapsed / 2\n\n\nasyncio.run(main())\n```",
